CREATE TABLE public.reader_demo_budget(day date PRIMARY KEY,calls integer NOT NULL DEFAULT 0 CHECK(calls>=0));
GRANT ALL ON public.reader_demo_budget TO service_role;
ALTER TABLE public.reader_demo_budget ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reader_demo_visitors(day date NOT NULL,visitor text NOT NULL,requests integer NOT NULL DEFAULT 0,PRIMARY KEY(day,visitor));
GRANT ALL ON public.reader_demo_visitors TO service_role;
ALTER TABLE public.reader_demo_visitors ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_public_oracle(p_visitor text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE used integer;BEGIN IF length(p_visitor)<>64 THEN RAISE EXCEPTION 'Visitante inválido.';END IF;INSERT INTO public.reader_demo_budget(day) VALUES(current_date) ON CONFLICT DO NOTHING;SELECT calls INTO used FROM public.reader_demo_budget WHERE day=current_date FOR UPDATE;IF used>=40 THEN RAISE EXCEPTION 'Demo temporalmente ocupado. Vuelve mañana.';END IF;INSERT INTO public.reader_demo_visitors(day,visitor) VALUES(current_date,p_visitor) ON CONFLICT DO NOTHING;SELECT requests INTO used FROM public.reader_demo_visitors WHERE day=current_date AND visitor=p_visitor FOR UPDATE;IF used>=3 THEN RAISE EXCEPTION 'Has usado las tres consultas del demo de hoy.';END IF;UPDATE public.reader_demo_visitors SET requests=requests+1 WHERE day=current_date AND visitor=p_visitor;UPDATE public.reader_demo_budget SET calls=calls+1 WHERE day=current_date;END$$;
REVOKE ALL ON FUNCTION public.claim_public_oracle(text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.claim_public_oracle(text) TO service_role;
ALTER POLICY reader_media_insert ON storage.objects WITH CHECK(false);
ALTER POLICY private_book_cover_insert ON storage.objects WITH CHECK(false);
CREATE OR REPLACE FUNCTION public.reader_preview(p_mode text,p_handle text DEFAULT '',p_club uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE viewer uuid;profile public.reader_social_profiles;contents jsonb;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.';END IF;SELECT * INTO STRICT profile FROM public.reader_social_profiles WHERE user_id=auth.uid();IF p_mode='friend' THEN SELECT user_id INTO STRICT viewer FROM public.reader_social_profiles WHERE handle=lower(trim(leading '@' FROM p_handle));IF NOT EXISTS(SELECT 1 FROM public.reader_friendships WHERE state='accepted' AND ((requester=auth.uid() AND recipient=viewer) OR (recipient=auth.uid() AND requester=viewer))) THEN RAISE EXCEPTION 'Elige una amistad aceptada.';END IF;ELSIF p_mode='club' THEN SELECT user_id INTO STRICT viewer FROM public.reader_social_profiles WHERE handle=lower(trim(leading '@' FROM p_handle));IF viewer=auth.uid() OR NOT koa_private.reader_club_member(p_club,auth.uid()) OR NOT koa_private.reader_club_member(p_club,viewer) THEN RAISE EXCEPTION 'Elige otro integrante de tu club.';END IF;ELSIF p_mode<>'public' THEN RAISE EXCEPTION 'Vista inválida.';END IF;IF NOT public.reader_preview_allows(auth.uid(),profile.visibility,profile.club_id,viewer) THEN RETURN jsonb_build_object('profile',NULL,'contents','[]'::jsonb);END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('kind',s.kind,'payload',public.reader_preview_payload(s.id,auth.uid(),viewer))) FILTER(WHERE public.reader_preview_allows(auth.uid(),s.visibility,s.club_id,viewer)),'[]'::jsonb) INTO contents FROM public.reader_shares s WHERE s.user_id=auth.uid();RETURN jsonb_build_object('profile',jsonb_build_object('handle',profile.handle,'name',profile.name,'bio',profile.bio,'avatar_path',profile.avatar_path,'cover_path',profile.cover_path),'contents',contents);END$$;